_EXTRACTED_NOW = False


def _zip_bytes() -> bytes:
    return base64.b64decode("".join(_B64.split()))


def _self_path() -> Path:
    return Path(__file__).resolve()


def _src_dir() -> Path:
    override = os.environ.get("BOTREFERAT_SRC", "").strip()
    if override:
        return Path(override).resolve()
    return _self_path().parent / SRC_DIR_NAME


def _verify_tree(target: Path) -> list:
    bad = []
    for name, sha, _size in _MANIFEST:
        p = target / name
        try:
            if hashlib.sha256(p.read_bytes()).hexdigest() != sha:
                bad.append(name)
        except OSError:
            bad.append(name)
    return bad


def _extract(force: bool = False, target: Path = None) -> Path:
    """Распаковка payload в target (по умолчанию _botsrc рядом с main.py).

    Идемпотентно: если_stamp совпадает с текущей сборкой — ничего не
    перезаписывает (сохраняются пользовательские файлы и кеши).
    """
    global _EXTRACTED_NOW
    if target is None:
        target = _src_dir()
    raw = _zip_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    stamp = target / ".bundle_stamp"
    if not force and stamp.is_file():
        try:
            if stamp.read_text(encoding="utf-8").strip() == digest:
                return target
        except OSError:
            pass
    target.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        for n in zf.namelist():
            if n.startswith("/") or ".." in n.replace("\\", "/").split("/"):
                raise SystemExit("[BUNDLE] подозрительное имя файла в payload: " + n)
        zf.extractall(str(target))
    bad = _verify_tree(target)
    if bad:
        raise SystemExit("[BUNDLE] контрольные суммы не сошлись: " + ", ".join(bad))
    (target / ".bundle_stamp").write_text(digest, encoding="utf-8")
    _EXTRACTED_NOW = True
    return target


def _sync_user_files(target: Path) -> None:
    """bot_config.json / .env из каталога рядом с единым main.py попадают
    в _botsrc (внешний файл — авторитетный источник конфигурации)."""
    here = _self_path().parent
    for name in ("bot_config.json", ".env"):
        src, dst = here / name, target / name
        try:
            if not src.is_file():
                continue
            if dst.is_file() and dst.read_bytes() == src.read_bytes():
                continue
            dst.write_bytes(src.read_bytes())
            print("[BUNDLE] %s скопирован рядом с main.py -> %s" % (name, target / name))
        except OSError:
            pass


def _launch(script: str) -> None:
    """Распаковать, подготовить окружение «как будто одна папка» и
    выполнить точку входа (main.py / train_perfect.py / diagnose...)."""
    target = _extract()
    _sync_user_files(target)
    if _EXTRACTED_NOW:
        print("[BUNDLE] Распаковано %d файлов (%d строк) в %s" % (N_FILES, N_LINES, target))
    os.chdir(str(target))
    if str(target) not in sys.path:
        sys.path.insert(0, str(target))
    path = target / script
    code = compile(path.read_text(encoding="utf-8"), str(path), "exec")
    globs = {
        "__name__": "__main__",
        "__file__": str(path),
        "__builtins__": __builtins__,
        "__package__": None,
        "__doc__": None,
    }
    exec(code, globs)


def _selfcheck() -> int:
    target = _extract()
    _sync_user_files(target)
    os.chdir(str(target))
    if str(target) not in sys.path:
        sys.path.insert(0, str(target))
    import importlib

    print("=" * 62)
    print("  САМОПРОВЕРКА ЕДИНОГО main.py (Botreferat v%s)" % VERSION)
    print("=" * 62)
    print("  Исходники : %s (%d файлов, %d строк)" % (target, N_FILES, N_LINES))

    deps = [
        ("aiogram", "Telegram-бот"),
        ("aiohttp", "HTTP/async"),
        ("docx", "python-docx"),
        ("PIL", "Pillow"),
        ("pypdf", "PDF"),
        ("fitz", "PyMuPDF"),
    ]
    missing = []
    for mod, why in deps:
        try:
            importlib.import_module(mod)
            print("  [OK]   %-8s %s" % (mod, why))
        except Exception as e:
            missing.append(mod)
            print("  [FAIL] %-8s %s — %r" % (mod, why, e))

    entry = {"main.py", "train_perfect.py", "diagnose_models.py", "rebuild_from_state.py"}
    testmods = sorted(n for n, _s, _z in _MANIFEST
                      if n.startswith("test_") and n.endswith(".py"))
    libs = [n for n, _s, _z in _MANIFEST
            if n.endswith(".py") and n not in entry and not n.startswith("test_")]
    fails = []
    for name in libs:
        try:
            importlib.import_module(name[:-3])
        except Exception as e:
            fails.append((name, repr(e)[:200]))
    print("  Модули бота : %d/%d импортированы без ошибок" % (len(libs) - len(fails), len(libs)))
    for name, err in fails:
        print("    [FAIL] %s: %s" % (name, err))

    comp_fail = []
    for name in sorted(entry | set(testmods)):
        try:
            compile((target / name).read_text(encoding="utf-8"), name, "exec")
        except Exception as e:
            comp_fail.append((name, repr(e)[:200]))
    print("  Точки входа + тесты (%d файлов): %s"
          % (len(entry) + len(testmods), "компилируются" if not comp_fail else "ОШИБКИ"))
    for name, err in comp_fail:
        print("    [FAIL] %s: %s" % (name, err))

    try:
        import zai_provider
        print("  Встроенный ИИ (zai): %s"
              % ("ДОСТУПЕН (GLM без внешних ключей)" if zai_provider.available()
                 else "недоступен: SDK/CLI не найдены"))
    except Exception as e:
        print("  Встроенный ИИ (zai): ошибка импорта %r" % e)

    try:
        import strict_prompts as SP
        print("  Жёсткие промпты: %d открытых критериев строгого преподавателя"
              % len(SP.TEACHER_CRITERIA))
    except Exception as e:
        print("  Жёсткие промпты: ошибка %r" % e)

    ok = not missing and not fails and not comp_fail
    print("=" * 62)
    print("  ИТОГ: %s" % ("ВСЁ ЗЕЛЁНО — единый файл работоспособен" if ok
                          else "ЕСТЬ ПРОБЛЕМЫ (см. выше)"))
    print("=" * 62)
    return 0 if ok else 1


def _ensure_out(rest: list, default_name: str = "generated") -> list:
    """Если --out не задан — выводим в <текущий каталог>/generated
    (дефолт train_perfect привязан к машине сборки и пользователю
    не подходит)."""
    if "--out" not in rest:
        return ["--out", str(Path.cwd() / default_name)] + rest
    return rest


def _absolutize_out(rest: list) -> list:
    """--out PATH делаем абсолютным ОТНОСИТЕЛЬНО исходного каталога
    пользователя (потом рабочий каталог сменится на _botsrc)."""
    out, i = [], 0
    while i < len(rest):
        a = rest[i]
        if a == "--out" and i + 1 < len(rest):
            p = Path(rest[i + 1])
            if not p.is_absolute():
                p = Path.cwd() / p
            out += ["--out", str(p)]
            i += 2
            continue
        out.append(a)
        i += 1
    return out


_GENERATE_HELP_TEMPLATE = """СГЕНЕРИРОВАТЬ РАБОТУ ЛОКАЛЬНО (без Telegram)

Использование:
  python3 main.py --generate --topic "Тема работы" [параметры]

Параметры:
  --topic     "..."    тема работы (ОБЯЗАТЕЛЬНО)
  --doc-type  X        тип работы: referat (по умолчанию) | kursovaya |
                       otchet (отчёт НИР) | esse | doklad | article | ...
  --subject   "..."    дисциплина (по умолчанию «Общая дисциплина»)
  --pages     N        объём в страницах (по умолчанию 14)
  --out       PATH     каталог результата (по умолчанию ./generated)
  --id        NAME     имя подкаталога результата (по умолчанию work)
  --max-cycles N       потолок циклов доработки (по умолчанию 8)

Конвейер: генерация каналов бота (встроенный ИИ) -> автотесты ->
рецензия СТРОГОГО преподавателя (10 открытых критериев) -> точечная
доработка -> повтор до вердикта IDEAL (оценка 5, все критерии >= 9).

Примеры:
  python3 main.py --generate --topic "Цифровая экономика России" \\
      --subject "Экономика" --pages 15
  python3 main.py --generate --doc-type kursovaya \\
      --topic "Профессиональный стресс у IT-специалистов" \\
      --subject "Психология труда" --pages 26 --out ./мои_работы
"""

GENERATE_HELP = _GENERATE_HELP_TEMPLATE


def main(argv: list) -> int:
    args = argv[1:]
    if not args or args[0] in ("--bot", "bot"):
        _launch("main.py")
        return 0
    cmd, rest = args[0], args[1:]
    if cmd in ("-V", "--version"):
        print("Botreferat v%s — единый main.py: %d файлов / %d строк в payload, сборка %s"
              % (VERSION, N_FILES, N_LINES, BUILD_DATE))
        return 0
    if cmd in ("-h", "--help"):
        print(__doc__)
        return 0
    if cmd == "--selfcheck":
        return _selfcheck()
    if cmd == "--extract":
        if rest:
            target = Path(rest[0]).resolve()
            _extract(target=target)
            print("Исходники распакованы в: %s" % target)
        else:
            print("Исходники распакованы в: %s" % _extract())
        return 0
    if cmd == "--train":
        sys.argv = ["train_perfect.py"] + _absolutize_out(_ensure_out(rest))
        _launch("train_perfect.py")
        return 0
    if cmd == "--generate":
        # Локальная генерация работы БЕЗ Telegram: тот же конвейер, что и
        # обучение (жёсткие промпты -> автотесты -> строгий преподаватель
        # -> доработка), но с дружелюбными дефолтами и понятным выводом.
        if not rest or rest[0] in ("-h", "--help"):
            print(GENERATE_HELP)
            return 0
        if "--topic" not in rest:
            print('Укажите тему работы: --topic "Тема вашей работы"',
                  file=sys.stderr)
            print(GENERATE_HELP)
            return 2
        rest = _ensure_out(rest)
        if "--max-cycles" not in rest:
            rest = ["--max-cycles", "8"] + rest
        if "--id" not in rest:
            rest = ["--id", "work"] + rest
        sys.argv = ["train_perfect.py"] + _absolutize_out(rest)
        print("[GENERATE] Работу создают каналы бота: встроенный ИИ (GLM),")
        print("[GENERATE] жёсткие промпты «на отлично», автотесты и рецензия")
        print("[GENERATE] строгого преподавателя; циклы доработки до IDEAL.")
        print("[GENERATE] Файлы появятся в подкаталоге work/ каталога --out.")
        _launch("train_perfect.py")
        return 0
    if cmd == "--diagnose":
        sys.argv = ["diagnose_models.py"] + rest
        _launch("diagnose_models.py")
        return 0
    print("Неизвестная команда: %s\n\n%s" % (cmd, __doc__), file=sys.stderr)
    return 2


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv))
    except KeyboardInterrupt:
        print("\n[BUNDLE] Остановлено пользователем")
        sys.exit(130)
